mapper.select:
SELECT 

FROM TBL_FINANCING_REPAYMENT_SCHEDULE


        AND FINANCING_NO LIKE CONCAT('%', #{financingNo}, '%')


        AND FINANCING_TYPE = #{financingType}


        AND FINANCIAL_INSTITUTION LIKE CONCAT('%', #{financialInstitution}, '%')


        AND REPAYMENT_STATUS = #{repaymentStatus}


        AND REPAYMENT_METHOD = #{repaymentMethod}


        AND PLANNED_REPAYMENT_DATE >= #{plannedRepaymentDateStart}


        AND PLANNED_REPAYMENT_DATE <= #{plannedRepaymentDateEnd}


        AND ACTUAL_REPAYMENT_DATE >= #{actualRepaymentDateStart}


        AND ACTUAL_REPAYMENT_DATE <= #{actualRepaymentDateEnd}


        AND CURRENCY = #{currency}


        AND REPAYMENT_STATUS IN (3, 4)


        AND OPERATOR LIKE CONCAT('%', #{operator}, '%')


        AND REVIEWER LIKE CONCAT('%', #{reviewer}, '%')


ORDER BY PLANNED_REPAYMENT_DATE DESC, REPAYMENT_PERIOD ASC
